svg.script:
(function () {
  var BASE = new URL("./", location.href).href;
  var frame = document.getElementById("homeFrame");
  var msg = document.getElementById("msg");
  function say(text) { msg.textContent = text; msg.style.display = text ? "flex" : "none"; }
  // The site's Home button calls this on the top window.
  window.desyncLoadHome = function () { frame.src = BASE + "main.html"; };
  frame.addEventListener("load", function () { if (frame.src) say(""); });
  if (!("serviceWorker" in navigator)) { say("This browser can't open the site here."); return; }
  navigator.serviceWorker.register(BASE + "proxy-sw.js", { scope: BASE })
    .then(function () { return navigator.serviceWorker.ready; })
    .then(function () { window.desyncLoadHome(); })
    .catch(function () { say("Couldn't start the site. Try reloading."); });
})();
